// Phân tích dữ liệu từ Telegram
const inputData = $('Trigger Prod').item.json;
const message = inputData.message || {};
const callbackQuery = inputData.callback_query || {};

const isCallback = !!callbackQuery.id;
const text = isCallback ? callbackQuery.data : (message.text || '');
const chatId = isCallback ? callbackQuery.message.chat.id : message.chat.id;
const messageId = isCallback ? callbackQuery.message.message_id : message.message_id;

let command = '';
let params = '';
let route = 'unknown';
let taskId = null;

if (text.startsWith('/')) {
  const parts = text.trim().split(' ');
  command = parts[0].toLowerCase();
  params = parts.slice(1).join(' ');

  // Nếu param chứa chitiet_, trích xuất taskId
  if (params.startsWith('chitiet_')) {
    taskId = params.replace('chitiet_', '').trim();
    params = 'chitiet';
    route = 'chitiet';
  } else {
    // Xác định route bình thường
    if (command.startsWith('/task')) route = 'task';
    else if (command === '/stat') route = 'stat';
    else if (command === '/taotask') {
      if (params.startsWith('td')) route = 'taotask_td';
      else route = 'taotask_tc';
    } else if (command === '/help') route = 'help';
    else route = 'unknown_command';
  }
} else {
  route = 'free_text';
  params = text;
}

// Xử lý callback riêng nếu cần
if (isCallback) {
  if (text.startsWith('view_task:')) {
    route = 'view_task';
    params = text.replace('view_task:', '');
  } else if (text === 'chat_claude') {
    route = 'chat_claude';
  } else if (text === 'use_clickup') {
    route = 'use_clickup';
  }
}

return {
  json: {
    route,
    command,
    params,
    taskId,
    chatId,
    messageId,
    isCallback,
    originalData: inputData
  }
};

// Lấy tất cả items
const allItems = $input.all();

const normalize = (s) =>
  s.normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase();

// Xử lý từng item
const processedData = allItems.map(({ json: item }) => {
  const raw = item.params || '';
  const words = raw.trim().split(/\s+/).filter(Boolean);
  const keywords = words.flatMap(word => [
    word,
    normalize(word),
    normalize(word).toLowerCase()
  ]);

  return {
    json: {
      ...item,
      searchKeywords: [...new Set(keywords)],
      originalText: raw,
      originalText_khong_dau: normalize(raw),
    }
  };
});

return processedData;

const inputItems = $input.all();

const originalContext = inputItems.find(i => i.json.chatId);
const chatId = originalContext?.json?.chatId || null;
const messageId = originalContext?.json?.messageId || null;
const searchText = originalContext?.json?.originalText || '';
const all = inputItems.filter(i => i.json.id).map(i => i.json);

const fullMatches = all.filter(i => i.fullMatch === true);
const partialMatches = all.filter(i => i.fullMatch !== true);
const botUsername = 'Elite_clickup_bot';

// Escape HTML
const escapeHtml = (text) => {
  return text?.replace(/&/g, '&amp;')
              .replace(/</g, '&lt;')
              .replace(/>/g, '&gt;') || '';
};

// Clean link: bỏ dấu nháy đơn và dấu ngoặc đơn
const cleanLink = (link) => {
  if (!link) return '';
  return link
    .replace(/^'+|'+$/g, '')     // bỏ dấu nháy đơn ở đầu/cuối
    .replace(/^\(+|\)+$/g, '')   // bỏ dấu ngoặc đơn ở đầu/cuối
    .trim();
};

// Format từng task
const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const matchScore = task.match_score !== undefined ? ` + (${task.match_score})` : '';
  const lines = [];

  lines.push(`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>`);
  lines.push(`├ Miêu tả: ${escapeHtml(task.description?.trim()) || '_Không rõ_'}`);
  lines.push(`├ Trạng thái: ${escapeHtml(task.status || '_Không rõ_')}${matchScore}`);
  lines.push(`├ List: ${task.list ? `7. ${escapeHtml(task.list)}` : '_Không rõ_'}`);
  lines.push(`├ Phụ trách: ${escapeHtml(task.phu_trach?.trim()) || '_Không rõ_'}`);

  if (task.DKPV) {
    lines.push(`├ Đăng kí phỏng vấn: ${escapeHtml(task.DKPV)}`);
  }

  if (task.PVTC) {
    lines.push(`├ Phỏng vấn thành công: ${escapeHtml(task.PVTC)}`);
  }

  if (task.onedrive_link) {
    const onedrive = cleanLink(task.onedrive_link);
    lines.push(`├ 📁 <a href="${onedrive}}">Xem OneDrive</a>`);
  }

  if (task.youtube_link) {
    lines.push(`├ 🎞️ Video:`);
    lines.push(` ${task.youtube_link}`);
  }

  lines.push(`└ 🔗 <a href="${cleanLink(task.url)}">Xem trong ClickUp</a>`);

  return lines.join('\n');
};

// Gộp kết quả
let message = '';
if (all.length === 0) {
  message = `❌ Không tìm thấy kết quả nào phù hợp với từ khóa <b>${escapeHtml(searchText)}</b>`;
} else {
  message += `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTrang 1/1 (Hiển thị ${all.length} kết quả)\n\n`;
  const combined = [...fullMatches, ...partialMatches];
  combined.forEach((task, i) => {
    message += formatTask(task, i) + '\n\n';
  });
  message = message.trim();
}

// Trả về
return [{
  json: {
    beautified: message,
    chatId,
    messageId,
    parse_mode: "HTML"
  }
}];

const items = $input.all();
let message = `📦 Danh sách file (Tổng có ${items.length} files):\n\n`;

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const fileName = data.name || "N/A";
  const fileType = data.file?.mimeType || "Unknown";
  const createdDate = new Date(data.createdDateTime).toLocaleString("en-GB", { timeZone: "Asia/Ho_Chi_Minh" });
  const creator = data.createdBy?.user?.displayName || "Unbekannt";

  // Sử dụng downloadUrl thay vì webUrl
  const fileUrl = data["@microsoft.graph.downloadUrl"] || data.webUrl || "#";

  message += `${i + 1}. [${fileName}](${fileUrl})\n🕒 Erstellt am: ${createdDate}\n👤 Von: ${creator}\n\n`;
}

return [{
  json: {
    telegramMessage: message.trim()
  }
}];

const input = $json;  // giữ lại toàn bộ input
const entities = input.originalData?.callback_query?.message?.entities || [];

// ✅ Tìm entity có chứa URL OneDrive
let oneDriveUrl = null;

for (const e of entities) {
  const url = e.url;
  if (url && (
    url.includes('1drv.ms') || 
    url.includes('onedrive.live.com/redir') || 
    url.includes('onedrive.live.com/?resid=')
  )) {
    oneDriveUrl = url;
    break;
  }
}

// Nếu không có URL, fallback (hoặc rỗng)
if (!oneDriveUrl || oneDriveUrl.trim() === '') {
  oneDriveUrl = "";
}

// ✅ Kiểm tra định dạng hợp lệ
function isValidShareUrl(url) {
  return url.includes('1drv.ms') || url.includes('onedrive.live.com/redir') || url.includes('onedrive.live.com/?resid=');
}

// ❌ Nếu không hợp lệ
if (!isValidShareUrl(oneDriveUrl)) {
  return [{
    json: {
      ...input,
      oneDriveUrl,
      error: `❌ Link OneDrive không hợp lệ hoặc bị lỗi nên không thể tự động upload.\n👉 Bạn có thể mở thủ công tại đây:\n${oneDriveUrl || 'Link không tồn tại.'}`
    }
  }];
}

// ✅ Nếu hợp lệ → mã hóa
const encoded = Buffer.from(oneDriveUrl)
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");

const shareId = `u!${encoded}`;
const apiUrl = `https://graph.microsoft.com/v1.0/shares/${shareId}/driveItem`;

return [{
  json: {
    ...input,
    oneDriveUrl,
    shareId,
    apiUrl
  }
}];

const inputItems = $input.all();
const originalContext = inputItems.find(i => i.json.chatId);
const chatId = originalContext?.json?.chatId || null;
const messageId = originalContext?.json?.messageId || null;
const searchText = originalContext?.json?.originalText || '';
const all = inputItems.filter(i => i.json.id).map(i => i.json);
