// Escape HTML
const escapeHtml = (text) =>
  text?.replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;") || '';

// Thời gian
const formatDate = str => {
  if (!str) return '';
  const d = new Date(str);
  const h = String(d.getHours()).padStart(2, '0');
  const m = String(d.getMinutes()).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = String(d.getFullYear()).slice(2);
  return `${h}:${m} ${day}/${month}/${year}`;
};

const cleanLink = (link) => {
  return link?.replace(/^'+|'+$/g, '') || '';
};

const botUsername = 'Elite_clickup_bot';

const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const matchScore = task.match_score !== undefined ? ` + (${task.match_score})` : '';
  const onedrive = task.onedrive_link ? cleanLink(task.onedrive_link) : '';
