  return (
`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>
├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}${matchScore}
├ List: ${task.list ? `7. ${escapeHtml(task.list)}` : 'Không rõ'}
├ Phụ trách: ${escapeHtml(task.phu_trach?.trim()) || 'Không rõ'}
${onedrive ? `├ 📁 <a href="${onedrive}">Xem OneDrive</a>` : ''}${task.youtube_link ? `\n├ 🎞️ Video:\n${task.youtube_link}` : ''}
└ 🔗 <a href="${clickupUrl}">Xem trong ClickUp</a>`
  );
};

let messages = [];

// Tin nhắn header đầu tiên
if (all.length === 0) {
  messages.push({
    json: {
      chatId,
      beautified: `❌ Không tìm thấy kết quả nào phù hợp với từ khóa <b>${escapeHtml(searchText)}</b>`,
      messageId,
      parse_mode: "HTML"
    }
  });
} else {
  // Header message
  const headerMessage = `🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy ${all.length} kết quả:`;
  messages.push({
    json: {
      chatId,
      beautified: headerMessage,
      messageId,
      parse_mode: "HTML"
    }
  });

  // Kết hợp full matches trước, partial matches sau
  const combined = [...fullMatches, ...partialMatches];

  // Tạo tin nhắn riêng cho từng task
  combined.forEach((task, index) => {
    const taskMessage = formatTask(task, index);
    messages.push({
      json: {
        chatId,
        beautified: taskMessage,
        messageId: null, // Để null cho các tin nhắn tiếp theo
        parse_mode: "HTML"
      }
    });
  });
}

return messages;

const input = $json; // Giữ nguyên toàn bộ nội dung

// Nội dung hướng dẫn lệnh Telegram
const helpText = `<b>📘 Danh sách lệnh Telegram</b>\n\n` +
  `👉 <code>/task &lt;từ khóa&gt;</code> – Tìm task\n` +
  `👉 <code>/task chitiet_&lt;id&gt;</code> – Chi tiết task\n` +
  `👉 <code>/taotask</code> – Tạo task mới\n` +
  `👉 <code>/taotask td</code> – Tạo task tuyển dụng\n\n` +
  `📁 <b>Upload / Xem OneDrive</b>: Dùng nút có sẵn\n\n` +
  `📌 <i>Ví dụ nhanh:</i>\n<code>/task linh nhi</code>\n<code>/task chitiet_86ervu2mt</code>`;

// Trả kết quả đã ghép text + giữ lại input gốc
return [{
  json: {
    ...input,
    text: helpText,
    parse_mode: "HTML"
  }
}];

const normalize = s => s
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D')
  .toLowerCase();

const results = $input.all().map(item => {
  const task = item.json;
  const keywords = Array.isArray(task.searchKeywords) ? task.searchKeywords.map(kw => normalize(kw)) : [];

  const name = normalize(task.name || '');
  const nameWords = name.split(/\s+/); // tách name thành các từ đơn đã chuẩn hóa

  // chỉ khớp nếu từ trong nameWords trùng hoàn toàn với keyword
  const matchWords = keywords.filter(kw => nameWords.includes(kw));

  const match_score = matchWords.length;
  const fullMatch = match_score === keywords.length;

  return {
    json: {
      ...task,
      match_score,
      max_score: keywords.length,
      fullMatch
    }
  };
});

return results;

const inputItems = $input.all();

const originalContext = inputItems.find(i => i.json.chatId || i.json.channelId);
const chatId = originalContext?.json?.chatId || originalContext?.json?.channelId || null;
const messageId = originalContext?.json?.messageId || null;
const searchText = originalContext?.json?.originalText || '';

const all = inputItems.filter(i => i.json.id).map(i => i.json);
const fullMatches = all.filter(i => i.fullMatch === true);
const partialMatches = all.filter(i => i.fullMatch !== true);

// Escape Markdown special characters for Discord (basic)
const escapeDiscord = (text) => {
  if (!text) return '';
  return text
    .replace(/\\/g, '\\\\')
    .replace(/\*/g, '\\*')
    .replace(/_/g, '\\_')
    .replace(/~/g, '\\~')
    .replace(/`/g, '\\`')
    .replace(/>/g, '\\>')
    .replace(/\|/g, '\\|');
};

// Escape và loại bỏ dấu ngoặc đơn (')
const escapeAndStrip = (text) => {
  if (!text) return '';
  return escapeDiscord(text).replace(/'/g, '');
};

// Hàm cleanLink cập nhật: loại bỏ dấu ', ký tự xuống dòng, trim
const cleanLink = (link) => {
  if (!link) return null;
  return link.trim().replace(/^'+|'+$/g, '').replace(/\n/g, '');
};

const botUsername = 'Elite_clickup_bot';

const formatTask = (task, index) => {
  const tgLink = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  // Nếu không có giá trị sẽ trả về null (đã chuẩn hóa sẵn)
  const onedriveLink = task.onedrive_link ? cleanLink(task.onedrive_link) : null;
  const clickupLink = task.url ? cleanLink(task.url) : null;
  const youtubeLinkRaw = task.youtube_link || null;
  const youtubeLink = youtubeLinkRaw ? cleanLink(youtubeLinkRaw) : null;

  const matchScore = task.match_score !== undefined ? ` (+${task.match_score})` : '';

  let text = `**${index + 1}. ${escapeAndStrip(task.name)}**` +
             `├ Trạng thái: ${escapeAndStrip(task.status) || 'Không rõ'}${matchScore}\n` +
             `├ Phụ trách: ${escapeAndStrip(task.phu_trach?.trim()) || 'Không rõ'}`;
  if (youtubeLink) {
    text += `\n\n${youtubeLink}`;
  }

  return {
    text,
    buttons: [
      {
        label: "Telegram Chi Tiết",
        url: tgLink
      },
      ...(onedriveLink ? [{
        label: "📁 Xem OneDrive",
        url: onedriveLink
      }] : []),
      ...(clickupLink ? [{
        label: "🔗 Xem trong ClickUp",
        url: clickupLink
      }] : [])
    ],
    youtubeLink: youtubeLink ?? null,
    onedriveLink: onedriveLink ?? null,
    clickupLink: clickupLink ?? null,
    channel: task.channel || task.originalData?.channel || null,
    channelId: task.channelId || task.originalData?.channelId || chatId || null,
    username: task.username || task.originalData?.username || null,
    userId: task.userId || task.originalData?.userId || null,
    originalData: task.originalData || null
  };
};

// Lấy kết quả hợp nhất
const combined = [...fullMatches, ...partialMatches];

// Giới hạn tối đa 10 items
const limitedTasks = combined.slice(0, 10);
const tasksFormatted = limitedTasks.map(formatTask);

let outputItems = [];

if (tasksFormatted.length === 0) {
  outputItems.push({
    json: {
      chatId,
      channelId: chatId,
      content: `❌ Không tìm thấy kết quả nào phù hợp với từ khóa **${escapeAndStrip(searchText)}**`,
      components: [],
      onedriveLink: null,
      youtubeLink: null,
      clickupLink: null,
      username: originalContext?.json?.username || null,
      userId: originalContext?.json?.userId || null,
      channel: originalContext?.json?.channel || null,
      originalData: originalContext?.json?.originalData || null,
    }
  });
} else {
  tasksFormatted.forEach((task, idx) => {
    outputItems.push({
      json: {
        chatId,
        channelId: task.channelId,
        content: task.text,
        components: task.buttons.length > 0 ? [{
          type: 1,
          components: task.buttons.map((btn, i) => ({
            type: 2,
            style: 5,
            label: btn.label,
            url: btn.url,
            custom_id: `button_${idx}_${i}`
          }))
        }] : [],
        embeds: task.youtubeLink ? [{
          type: "video",
          url: task.youtubeLink
        }] : undefined,
        channel: task.channel,
        username: task.username,
        userId: task.userId,
        onedriveLink: task.onedriveLink,
        youtubeLink: task.youtubeLink,
        clickupLink: task.clickupLink,
        originalData: task.originalData
      }
    });
  });
}

return outputItems;

