// n8n Code node (JavaScript)
// Transform Telegram-like input -> { route, command, params, ... }

function computeRoute(command, params, isCallback, rawText) {
  // Ưu tiên xử lý callback_query
  if (isCallback) {
    if (rawText?.startsWith('view_task:')) return { route: 'view_task', params: rawText.replace('view_task:', '') };
    if (rawText === 'chat_claude') return { route: 'chat_claude', params: '' };
    if (rawText === 'use_clickup') return { route: 'use_clickup', params: '' };
  }

  // Mặc định
  let route = 'unknown';
  let taskId = null;
  let p = params || '';

  // Đặc biệt: "chitiet_<id>" -> route "chitiet"
  if (p.startsWith('chitiet_')) {
    taskId = p.replace('chitiet_', '').trim();
    p = 'chitiet';
    route = 'chitiet';
    return { route, params: p, taskId };
  }

  // Route theo lệnh
  if (command.startsWith('/task')) route = 'task';
  else if (command === '/stat') route = 'stat';
  else if (command === '/taotask') {
    if (p.startsWith('td')) route = 'taotask_td';
    else route = 'taotask_tc';
  } else if (command === '/help') route = 'help';
  else if (!command && p) route = 'free_text';
  else route = 'unknown_command';

  return { route, params: p, taskId };
}

function mapOne(original) {
  const inputData = original || {};
  const message = inputData.message || {};
  const callbackQuery = inputData.callback_query || {};

  const isCallback = !!callbackQuery.id;
  const text = isCallback ? (callbackQuery.data || '') : (message.text || '');
  const chatId = isCallback ? (callbackQuery.message?.chat?.id) : (message.chat?.id);
  const messageId = isCallback ? (callbackQuery.message?.message_id) : (message.message_id);

  // Tách command/params từ text
  let command = '';
  let params = '';
  if ((text || '').startsWith('/')) {
    const parts = text.trim().split(/\s+/);
    command = (parts[0] || '').toLowerCase();
    params = parts.slice(1).join(' ');
  } else {
    // free text
    params = text || '';
  }

  const { route, params: finalParams, taskId } = computeRoute(command, params, isCallback, text);

  return {
    json: {
      route,
      command,
      params: finalParams,
      taskId: taskId ?? null,
      chatId: chatId ?? null,
      messageId: messageId ?? null,
      isCallback,
      originalData: inputData, // giữ nguyên dữ liệu gốc để bạn trace/debug
    }
  };
}

// Nhận mọi item từ upstream
const items = $input.all();

// Trường hợp upstream đưa thẳng mảng JSON ở item đầu tiên
if (items.length === 1 && Array.isArray(items[0].json)) {
  const arr = items[0].json;
  const out = arr.map(obj => mapOne(obj));
  return out;
}

// Mặc định: xử lý từng item.json
return items.map(it => mapOne(it.json));

// n8n Code node: add file extension to data.file_name using mimetype or filename
// Input: items[].json.data = { file: { filename, mimetype, size }, file_name }
// Output fields:
//   data.file_name_final  -> tên cuối cùng có ext
//   data._ext_source      -> 'mimetype' | 'filename' | 'unknown'
//   data._ext             -> ext xác định (không có dấu chấm)

const MIME_TO_EXT = {
  // images
  "image/jpeg": "jpg",
  "image/jpg": "jpg",
  "image/pjpeg": "jpg",
  "image/png": "png",
  "image/gif": "gif",
  "image/webp": "webp",
  "image/heic": "heic",
  "image/heif": "heif",
  "image/tiff": "tif",
  "image/bmp": "bmp",
  "image/svg+xml": "svg",

  // docs
  "application/pdf": "pdf",
  "application/msword": "doc",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
  "application/vnd.ms-excel": "xls",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "text/csv": "csv",
  "text/plain": "txt",
  "application/json": "json",

  // video
  "video/mp4": "mp4",
  "video/quicktime": "mov",
  "video/x-msvideo": "avi",
  "video/x-matroska": "mkv",
  "video/webm": "webm",

  // audio
  "audio/mpeg": "mp3",
  "audio/mp3": "mp3",
  "audio/wav": "wav",
  "audio/x-wav": "wav",
  "audio/ogg": "ogg",
  "audio/mp4": "m4a",

  // archives
  "application/zip": "zip",
  "application/x-rar-compressed": "rar",
  "application/x-7z-compressed": "7z",
};

function safeString(s) {
  return (s ?? "").toString().trim();
}

function extFromFilename(filename) {
  const name = safeString(filename);
  // Lấy phần mở rộng ở cuối .abc (1-8 ký tự chữ/số)
  const m = name.match(/\.([a-z0-9]{1,8})$/i);
  if (!m) return "";
  let ext = m[1].toLowerCase();
  // Chuẩn hóa vài biến thể
  if (ext === "jpeg") ext = "jpg";
  if (ext === "tiff") ext = "tif";
  return ext;
}

function extFromMime(mime) {
  const m = safeString(mime).toLowerCase();
  if (!m) return "";
  if (MIME_TO_EXT[m]) return MIME_TO_EXT[m];
  // fallback cho loại như "image/xyz"
  const parts = m.split("/");
  if (parts.length === 2) {
    let raw = parts[1];
    if (raw === "jpeg") raw = "jpg";
    if (raw === "tiff") raw = "tif";
    // loại bỏ phần +xml, +json...
    raw = raw.replace(/\+.*/g, "");
    // chỉ giữ chữ/số
    raw = raw.replace(/[^a-z0-9]/g, "");
    return raw || "";
  }
  return "";
}

function hasExt(name) {
  return /\.[a-z0-9]{1,8}$/i.test(name);
}

function addExt(base, ext) {
  if (!ext) return base;               // không đoán được ext → giữ nguyên
  if (hasExt(base)) return base;       // đã có ext → không thêm nữa
  return `${base}.${ext}`;
}

const out = items.map((item) => {
  const data = (item.json && item.json.data) || {};
  const file = data.file || {};
  const origName = safeString(data.file_name);          // tên không ext (mong muốn)
  const uploadFilename = safeString(file.filename);     // tên gốc khi upload (có ext)
  const mimetype = safeString(file.mimetype);

  // Ưu tiên mimetype -> filename
  let ext = extFromMime(mimetype);
  let extSource = "mimetype";
  if (!ext) {
    ext = extFromFilename(uploadFilename);
    extSource = ext ? "filename" : "unknown";
  }

  // Nếu không có file_name, fallback về tên upload không đuôi
  let baseName = origName || uploadFilename.replace(/\.[a-z0-9]{1,8}$/i, "");
  baseName = baseName.trim();

  const finalName = addExt(baseName, ext);

  return {
    json: {
      ...item.json,
      data: {
        ...data,
        file_name_final: finalName,
        _ext_source: extSource,
        _ext: ext,
      },
    },
  };
});

return out;

// n8n Code node: split a very long telegramMessage into safe chunks for Telegram
// Input: items[0].json.telegramMessage (string)
// Output: multiple items: { json: { telegramMessage: <chunk>, part: i, total: n } }

const MAX = 3500; // safe margin under Telegram ~4096
const inputItems = $input.all();
if (!inputItems.length) {
  return [{ json: { telegramMessage: 'Không có dữ liệu đầu vào.' } }];
}

let text = (inputItems[0].json.telegramMessage ?? '').toString();

// (tùy chọn) loại bỏ dấu ngoặc nhọn thừa trong link (nếu có)
text = text.replace(/[{}]/g, '');

// --- 1) Cắt thành các "khối" theo khoảng trắng/đoạn (ưu tiên không bể link) ---
/*
  Heuristic:
  - Mỗi item thường cách nhau bằng 1 dòng trống.
  - Ta split theo 2+ newline để tạo block tương đối nguyên vẹn.
*/
let rawBlocks = text.split(/\n{2,}/);

// Giữ lại header vào block đầu (nếu có). Không cần logic riêng—đã nằm trong rawBlocks[0].

// --- 2) Nén các block vào các chunk <= MAX ---
const chunks = [];
let current = '';

function pushCurrent() {
  if (current.trim().length > 0) chunks.push(current.trim());
  current = '';
}

function appendBlockToCurrent(block) {
  // Thêm block vào current, chèn "\n\n" nếu cần
  const sep = current.length ? '\n\n' : '';
  if ((current.length + sep.length + block.length) <= MAX) {
    current += sep + block;
    return true;
  }
  return false;
}

function smartSplitBlock(block) {
  // Nếu block quá dài, cố tìm điểm cắt "an toàn":
  // 1) vị trí ')' + newline gần MAX (kết thúc link)
  // 2) vị trí '\n' gần MAX
  // 3) nếu không có, cắt cứng tại MAX
  let start = 0;
  while (start < block.length) {
    let remaining = block.slice(start);
    if (remaining.length <= MAX) {
      // nhét phần còn lại vào chunk mới
      if (!appendBlockToCurrent(remaining)) {
        pushCurrent();
        current = remaining;
      }
      break;
    }

    // tìm cut pos an toàn trong khoảng [0 .. MAX]
    let window = remaining.slice(0, MAX);

    // ưu tiên kết thúc link: ')\n' hoặc ') ' (nhiều link markdown sẽ theo sau là newline)
    let cut = Math.max(window.lastIndexOf(')\n'), window.lastIndexOf(') '));
    // nếu vẫn không có, thử newline gần cuối
    if (cut < 0) cut = window.lastIndexOf('\n');
    // cuối cùng, cắt cứng
    if (cut < 0) cut = MAX;

    let piece = remaining.slice(0, cut).trimEnd();

    if (!appendBlockToCurrent(piece)) {
      pushCurrent();
      current = piece;
    }

    start += cut;
    // bỏ ký tự xuống dòng nếu có để tránh lặp vô hạn
    while (start < block.length && (block[start] === '\n' || block[start] === ' ')) start++;
  }
}

// Đưa từng block vào các chunk
for (const block of rawBlocks) {
  if (!block) continue;

  if (!appendBlockToCurrent(block)) {
    // block này không fit -> kết thúc current, tạo chunk mới
    if (current) pushCurrent();

    if (block.length <= MAX) {
      current = block;
    } else {
      // block quá lớn -> tách thông minh
      smartSplitBlock(block);
    }
  }
}

// đẩy phần cuối cùng
pushCurrent();

// --- 3) (tùy chọn) thêm tiêu đề tiếp tục cho các phần sau ---
const total = chunks.length;
const header = (s) => s;
const contHeader = (i, n) => `📦 (tiếp) – phần ${i}/${n}\n\n`;

const out = [];
for (let i = 0; i < total; i++) {
  const isFirst = i === 0;
  const prefix = isFirst ? '' : contHeader(i + 1, total);
  out.push({
    json: {
      telegramMessage: (prefix + chunks[i]).trim(),
      part: i + 1,
      total,
    },
  });
}

return out;

// n8n Code node (JavaScript)
// Extract chatId, messageId, userId, userName from HTTP webhook-like input

function computeRoute(command, params, rawText) {
  let route = 'unknown';
  let taskId = null;
  let p = params || '';

  if (p.startsWith('chitiet_')) {
    taskId = p.replace('chitiet_', '').trim();
    p = 'chitiet';
    route = 'chitiet';
    return { route, params: p, taskId };
  }

  if (command.startsWith('/task')) route = 'task';
  else if (command === '/stat') route = 'stat';
  else if (command === '/taotask') {
    if (p.startsWith('td')) route = 'taotask_td';
    else route = 'taotask_tc';
  } else if (command === '/help') route = 'help';
  else if (!command && p) route = 'free_text';
  else route = 'unknown_command';

  return { route, params: p, taskId };
}

function mapOne(enveloped) {
  const body = enveloped.body || {};
  const message = body.message || {};

  // Lấy trực tiếp các field theo yêu cầu
  const chatId = message.chat?.id ?? null;
  const messageId = message.message_id ?? null;
  const userId = message.from?.id ?? null;
  const userName = message.from?.display_name ?? null;
  const rawText = message.text || '';

  // Parse command/params từ text
  let command = '';
  let p = '';
  if ((rawText || '').startsWith('/')) {
    const parts = rawText.trim().split(/\s+/);
    command = (parts[0] || '').toLowerCase();
    p = parts.slice(1).join(' ');
  } else {
    p = rawText || '';
  }

  const { route, params, taskId } = computeRoute(command, p, rawText);

  return {
    json: {
      route,
      command,
      params,
      taskId: taskId ?? null,
      chatId,
      messageId,
      userId,
      userName,
      text: rawText,
      originalData: enveloped, // giữ nguyên để debug
    }
  };
}

const items = $input.all();

// Trường hợp đầu vào là một mảng JSON trong item đầu tiên
if (items.length === 1 && Array.isArray(items[0].json)) {
  return items[0].json.map(obj => mapOne(obj));
}

// Mặc định: xử lý từng item.json
return items.map(it => mapOne(it.json));

// Adapter Gateway: chuan hoa Message Envelope (spec ARCHITECTURE.md muc 3)
// thanh shape Telegram update cu (message / callback_query) ma node 'Code'
// (da co san, dang bi disable) dang can de tinh route/command/params/taskId.
// Giu nguyen toan bo field envelope goc bang cach spread ra root truoc,
// de request_id/platform/auth/bot_key van con trong originalData khi debug.
const items = $input.all();
return items.map(it => {
  const env = it.json ?? {};
  const isCallback = env.kind === 'callback';
  const out = { ...env };
  if (isCallback) {
    out.callback_query = {
      id: env.callback?.id,
      data: env.callback?.data,
      message: {
        chat: { id: env.chat_id },
        message_id: env.callback?.message_id
      }
    };
  } else {
    out.message = {
      text: env.text || '',
      chat: { id: env.chat_id },
      message_id: env.raw?.message_id ?? null,
      from: { id: env.user_id, username: env.username }
    };
  }
  return { json: out };
});
